"""Stateful replay preparation.

A usable preparation is a path of enabled transitions from the initial state
to the recovered desired state, minimising ``(sum of costs, number of
commands, command sequence lexicographically)`` exactly.  Guards are evaluated
on the recovered entry inputs, so a run's enabled transition set is fixed and
plans can be cached per run shape.
"""

from heapq import heapify, heappop, heappush

_MISSING = object()


class StateMachine(object):
    """A compiled campaign state machine."""

    def __init__(self, spec, freeze=None):
        self.states = list(spec['states'])
        self.index = {state: position for position, state in enumerate(self.states)}
        self.initial = self.index[spec['initial']]
        self.state_param = spec['state_param']
        self.message_param = spec['message_param']
        self.transitions = []
        self.guard_keys = []
        self.guard_sources = []
        for transition in spec['transitions']:
            source = transition['from']
            target = transition['to']
            self.transitions.append((
                self.index[source],
                self.index[target],
                transition['command'],
                int(transition['cost']),
            ))
            guard = transition.get('when')
            self.guard_sources.append(guard)
            self.guard_keys.append(None if guard is None else freeze(guard))
        self.adjacency = [[] for _ in self.states]
        for position, (source, target, command, cost) in enumerate(self.transitions):
            self.adjacency[source].append((target, cost, command, position))
        self._cache = {}

    def plan(self, target, enabled):
        """Return ``(cost, commands)`` for ``target`` or ``None``."""
        disabled = []
        for position, active in enumerate(enabled):
            if not active:
                disabled.append(position)
        key = (target, tuple(disabled))
        cached = self._cache.get(key, _MISSING)
        if cached is not _MISSING:
            return cached
        prepared = self._solve(target, enabled)
        if len(self._cache) >= 4096:
            self._cache.clear()
        self._cache[key] = prepared
        return prepared

    def _solve(self, target, enabled):
        count = len(self.states)
        adjacency = self.adjacency
        # Cheapest reachable cost per state.
        cost = [-1] * count
        cost[self.initial] = 0
        heap = [(0, self.initial)]
        while heap:
            here, state = heappop(heap)
            if here > cost[state]:
                continue
            for next_state, weight, command, position in adjacency[state]:
                if not enabled[position]:
                    continue
                candidate = here + weight
                if cost[next_state] < 0 or candidate < cost[next_state]:
                    cost[next_state] = candidate
                    heappush(heap, (candidate, next_state))
        if cost[target] < 0:
            return None
        # Fewest commands among the cheapest paths: every prefix of a
        # minimum-cost path is itself minimum-cost, so tight edges only.
        states = [state for state in range(count) if cost[state] >= 0]
        states.sort(key=lambda state: cost[state])
        hops = [None] * count
        hops[self.initial] = 0
        tight = []
        for state in states:
            here = hops[state]
            if here is None:
                continue
            base = cost[state]
            for next_state, weight, command, position in adjacency[state]:
                if not enabled[position] or cost[next_state] != base + weight:
                    continue
                tight.append((state, next_state, command))
                candidate = here + 1
                if hops[next_state] is None or candidate < hops[next_state]:
                    hops[next_state] = candidate
        graph = [[] for _ in range(count)]
        reverse = [[] for _ in range(count)]
        for source, next_state, command in tight:
            if hops[source] is not None and hops[next_state] == hops[source] + 1:
                graph[source].append((next_state, command))
                reverse[next_state].append(source)
        # States that can still reach the target inside the tight graph.
        reach = [False] * count
        reach[target] = True
        stack = [target]
        while stack:
            state = stack.pop()
            for previous in reverse[state]:
                if not reach[previous]:
                    reach[previous] = True
                    stack.append(previous)
        if not reach[self.initial]:
            return None
        # Greedy lexicographic walk over the surviving commands.
        commands = []
        state = self.initial
        while state != target:
            best = None
            for next_state, command in graph[state]:
                if reach[next_state] and (best is None or command < best[1]):
                    best = (next_state, command)
            if best is None:
                return None
            commands.append(best[1])
            state = best[0]
        return cost[target], commands


#: Historic name.
Machine = StateMachine


def BFS(transition_dict, target_state, initial='INITIAL'):
    """Unweighted breadth-first command search kept for simple machines."""
    from collections import deque
    queue = deque()
    queue.append((initial, []))
    visited = {initial}
    while queue:
        state, sequence = queue.popleft()
        if state == target_state:
            return sequence
        for (source, command), next_state in transition_dict.items():
            if source == state and next_state not in visited:
                visited.add(next_state)
                queue.append((next_state, sequence + [command]))
    return None


def prepare(machine, target, assignment, predicate):
    """Guarded preparation helper for a single record."""
    enabled = []
    for index, guard in enumerate(machine.guard_sources):
        if predicate is None or guard is None:
            enabled.append(True)
        else:
            enabled.append(bool(predicate(guard, assignment)))
    result = machine.plan(target, enabled)
    if result is None:
        return None
    return result[0], result[1]
